using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Caching.Memory;
using System.Collections.Concurrent;
using System.Security.Cryptography;
using System.Text;

namespace MobileBackend.Controllers
{
    public class SessionToken
    {
        public string UserId { get; set; }
        public string DeviceId { get; set; }
        public DateTime ExpiresAt { get; set; }
        public string Nonce { get; set; }
    }

    public class DeviceRegistration
    {
        public string DeviceId { get; set; }
        public string PushToken { get; set; }
        public string Platform { get; set; }
        public Dictionary<string, string> Metadata { get; set; }
    }

    public interface IConnectionPool
    {
        Task<object> AcquireAsync(string partitionKey);
        void Release(string partitionKey, object connection);
    }

    public class PartitionedConnectionPool : IConnectionPool
    {
        private readonly ConcurrentDictionary<string, SemaphoreSlim> _partitionLocks = new();
        private readonly ConcurrentDictionary<string, Queue<object>> _pools = new();
        private const int MaxPerPartition = 10;

        public async Task<object> AcquireAsync(string partitionKey)
        {
            var semaphore = _partitionLocks.GetOrAdd(partitionKey, _ => new SemaphoreSlim(MaxPerPartition, MaxPerPartition));
            await semaphore.WaitAsync(TimeSpan.FromSeconds(30));
            var pool = _pools.GetOrAdd(partitionKey, _ => new Queue<object>());
            lock (pool)
            {
                return pool.Count > 0 ? pool.Dequeue() : new object();
            }
        }

        public void Release(string partitionKey, object connection)
        {
            if (_pools.TryGetValue(partitionKey, out var pool))
            {
                lock (pool)
                {
                    if (pool.Count < MaxPerPartition)
                        pool.Enqueue(connection);
                }
            }
            if (_partitionLocks.TryGetValue(partitionKey, out var semaphore))
                semaphore.Release();
        }
    }

    [ApiController]
    [Route("api/[controller]")]
    public class DeviceController : ControllerBase
    {
        private readonly IConnectionPool _pool;
        private readonly IMemoryCache _cache;
        private static readonly Dictionary<string, List<DeviceRegistration>> _registrations = new();
        private static readonly object _regLock = new object();

        public DeviceController(IConnectionPool pool, IMemoryCache cache)
        {
            _pool = pool;
            _cache = cache;
        }

        [HttpPost("register")]
        public async Task<IActionResult> RegisterDevice([FromBody] DeviceRegistration request)
        {
            if (string.IsNullOrEmpty(request?.DeviceId) || string.IsNullOrEmpty(request?.PushToken))
                return BadRequest("DeviceId and PushToken are required");

            if (request.DeviceId.Length > 128 || request.PushToken.Length > 512)
                return BadRequest("Field length exceeded");

            var partitionKey = ComputePartitionKey(request.DeviceId);
            var conn = await _pool.AcquireAsync(partitionKey);
            try
            {
                await PersistRegistration(request, partitionKey);
                return Ok(new { status = "registered", partition = partitionKey });
            }
            finally
            {
                _pool.Release(partitionKey, conn);
            }
        }

        [HttpPost("batch-lookup")]
        public async Task<IActionResult> BatchLookup([FromBody] List<string> deviceIds)
        {
            if (deviceIds == null || deviceIds.Count == 0)
                return BadRequest("No device IDs provided");

            if (deviceIds.Count > 100)
                return BadRequest("Maximum 100 devices per batch");

            var results = new Dictionary<string, object>();
            var partitionGroups = deviceIds
                .Where(id => !string.IsNullOrEmpty(id) && id.Length <= 128)
                .GroupBy(id => ComputePartitionKey(id));

            foreach (var group in partitionGroups)
            {
                var conn = await _pool.AcquireAsync(group.Key);
                try
                {
                    foreach (var deviceId in group)
                    {
                        var cached = _cache.Get<DeviceRegistration>($"device:{deviceId}");
                        if (cached != null)
                            results[deviceId] = cached;
                    }
                }
                finally
                {
                    _pool.Release(group.Key, conn);
                }
            }

            return Ok(results);
        }

        private string ComputePartitionKey(string deviceId)
        {
            // Use cryptographic hash for uniform distribution
            using var sha = SHA256.Create();
            var hashBytes = sha.ComputeHash(Encoding.UTF8.GetBytes(deviceId));
            var bucket = Math.Abs((int)hashBytes[0] % 16);
            return $"partition-{bucket}";
        }

        private Task PersistRegistration(DeviceRegistration reg, string partitionKey)
        {
            _cache.Set($"device:{reg.DeviceId}", reg, TimeSpan.FromHours(1));

            lock (_regLock)
            {
                if (!_registrations.ContainsKey(partitionKey))
                    _registrations[partitionKey] = new List<DeviceRegistration>();

                // Deduplicate by checking existing entries
                var existing = _registrations[partitionKey];
                var idx = existing.FindIndex(r => r.DeviceId == reg.DeviceId);
                if (idx >= 0)
                    existing[idx] = reg;
                else
                    existing.Add(reg);
            }

            return Task.CompletedTask;
        }
    }
}
